	if strings.Contains(block.Body, "{{interactsh-url}}") {
		return true
	}
	for _, value := range block.Headers {
		if strings.Contains(value, "{{interactsh-url}}") {
			return true
		}
	}
	for _, raw := range block.Raw {
		if strings.Contains(raw, "{{interactsh-url}}") {
			return true
		}
	}
	return false
