334: // CancelNucleiJob stops a running job. It reports false when the job is
335: // unknown or already finished, so a second cancel is not silently accepted.
336: func CancelNucleiJob(id string) bool {
337: 	job, ok := nucleiJobs.get(strings.TrimSpace(id))
338: 	if !ok {
339: 		return false
340: 	}
341: 	job.mutex.Lock()
342: 	phase := job.progress.Phase
343: 	jobActiveNow := jobActive(phase)
344: 	// A stopped process does not react to the context until it is continued, so
345: 	// cancelling a paused run has to hand the signal over first. resumeLocked
346: 	// documents that the caller must hold the job mutex, and that is not
347: 	// formality: the stats goroutine reads the same `paused` flag from
348: 	// setProgressLocked to decide whether a line in the pipe still describes a
349: 	// paused run. Releasing the lock between the two decisions let a stats line
350: 	// read the flag mid-update, which is the one case the flag exists for.
351: 	if jobActiveNow {
352: 		job.resumeLocked()
353: 	}
354: 	job.mutex.Unlock()
355: 	if !jobActiveNow {
356: 		return false
357: 	}
358: 	job.cancel()
359: 	return true
360: }
