	return lines[len(lines)-1]
}

func tailStats(lines []string, n int) []string {
	if len(lines) <= n {
		return lines
	}
	return lines[len(lines)-n:]
}

func lastStatsSeconds(lines []string) float64 {
	if len(lines) == 0 {
