async function persistScannerTemplateContents() {
  const flat = scannerCollectedFiles();
  // Writing tens of megabytes on every render would be wasted work: the list is
  // redrawn when it is restored as well as when it changes, and the contents are
  // identical either way. The signature is cheap to compare and skips the write
  // whenever the selection is what was stored last.
  const signature = scannerTemplateSignature(flat);
  if (signature === scannerTemplateStoreSignature) return;
  if (!flat.length) {
    scannerTemplateStoreSignature = signature;
    await clearScannerTemplateContents();
    return;
  }
  try {
    const database = await openScannerTemplateStore('readwrite');
    await new Promise((resolve, reject) => {
      const transaction = database.transaction('templates', 'readwrite');
      transaction.objectStore('templates').put({
        id: 'scanner',
        files: flat.map(({name, path, content}) => ({name, path, content})),
        savedAt: Date.now()
      });
      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
      transaction.onabort = () => reject(transaction.error);
    });
    database.close();
    scannerTemplateStoreSignature = signature;
  } catch (error) {
    // The signature is left unset, so the next attempt tries again instead of
    // assuming the contents are safely stored.
    // The contents stay on disk for this session either way; only the ability to
    // come back to them after a reload is lost, and the operator is told so.
    setWorkspaceSnapshotNotice(tr('scanner.templatesNotStored', {message: error.message}));
  }
}

async function clearScannerTemplateContents() {
  try {
    const database = await openScannerTemplateStore('readwrite');
    await new Promise((resolve, reject) => {
      const transaction = database.transaction('templates', 'readwrite');
      transaction.objectStore('templates').delete('scanner');
      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
    });
    database.close();
  } catch (error) {
    console.warn('Staged template contents could not be cleared:', error);
  }
}

async function readScannerTemplateContents() {
  scannerTemplateContentsPending = true;
  syncScannerRunAvailability();
  try {
    const database = await openScannerTemplateStore('readonly');
    const stored = await new Promise((resolve, reject) => {
      const request = database.transaction('templates', 'readonly').objectStore('templates').get('scanner');
      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => reject(request.error);
    });
    database.close();
    if (!stored || !Array.isArray(stored.files) || !stored.files.length) return null;
    // What came back is already in the store, so the first redraw after a reload
    // must not rewrite it.
    const files = stored.files;
