function splitUploadChunks(files) {
  const chunks = [];
  let current = [];
  let size = 0;
  files.forEach(file => {
    const bytes = file.content.length;
    if (current.length && size + bytes > SCANNER_CHUNK_BYTES) {
      chunks.push(current);
      current = [];
      size = 0;
    }
    current.push(file);
    size += bytes;
  });
  if (current.length) chunks.push(current);
  return chunks;
}

