		writeError(w, status, code, err)
		return
	}
	state := scanner.JobRunning
	if action == "cancel" {
		state = scanner.JobCancelled
	} else if action == "pause" {
		state = scanner.JobPaused
	}
	writeJSON(w, http.StatusOK, map[string]interface{}{"job_id": id, "state": state})
}

