"""Діагностика Cancel: що реально відповідає сервер і що робить клієнт.

Обгортає `fetch` і `EventSource` всередині сторінки, щоб бачити відповіді
cancel і життя SSE-потоку, а не лише DOM.
"""

import sys
import time

from playwright.sync_api import sync_playwright

BASE = "http://127.0.0.1:8000"
CORPUS = "/home/kali/Desktop/DevBackUp-vecher07101/nuclei-templates/javascript"

INSTRUMENT = """
(() => {
  window.__probe = {fetches: [], streams: []};
  const realFetch = window.fetch;
  window.fetch = async function (input, init) {
    const url = typeof input === 'string' ? input : (input && input.url) || '';
    try {
      const res = await realFetch.call(this, input, init);
      if (url.includes('/api/scanner/nuclei/')) {
        let body = '';
        try { body = await res.clone().text(); } catch (e) { body = 'ERR ' + e.message; }
        window.__probe.fetches.push({url: url, method: (init && init.method) || 'GET',
                                      status: res.status, body: body.slice(0, 200)});
      }
      return res;
    } catch (e) {
      if (url.includes('/api/scanner/nuclei/')) {
        window.__probe.fetches.push({url: url, method: (init && init.method) || 'GET',
                                      status: -1, body: 'THREW ' + e.message});
      }
      throw e;
    }
  };
  const RealES = window.EventSource;
  window.EventSource = function (url) {
    const es = new RealES(url);
    window.__probe.streams.push({url: String(url), opened: true, closed: false});
    const realClose = es.close.bind(es);
    es.close = function () {
      window.__probe.streams[window.__probe.streams.length - 1].closed = true;
      return realClose();
    };
    return es;
  };
  window.EventSource.prototype = RealES.prototype;
})();
"""


def main() -> int:
    start = time.time()
    with sync_playwright() as play:
        browser = play.firefox.launch(headless=True)
        page = browser.new_page(viewport={"width": 1356, "height": 652})
        page.add_init_script(INSTRUMENT)
        page.goto(BASE + "/", wait_until="domcontentloaded", timeout=60_000)
        page.click('nav [data-tab="scanner"]')
        page.wait_for_timeout(400)
        page.click("#scanner-view-nuclei")
        page.fill("#scanner-url", "https://yandex.ru")
        page.set_input_files("#scanner-yaml-dir", CORPUS)
        page.wait_for_timeout(2500)

        page.click("#scanner-templates-run")
        page.wait_for_timeout(6000)
        print("== after start ==")
        print("  phase:", repr(page.inner_text("#scanner-progress-phase").strip()))
        print("  streams:", page.evaluate("() => window.__probe.streams"))

        page.click("#scanner-progress-cancel")
        page.wait_for_timeout(4000)
        print("\n== after Cancel ==")
        print("  phase:", repr(page.inner_text("#scanner-progress-phase").strip()))
        print("  status:", repr(page.inner_text("#scanner-status").strip()))
        print("  run enabled:", page.is_enabled("#scanner-templates-run"))
        print("  streams:", page.evaluate("() => window.__probe.streams"))
        print("  fetches:")
        for item in page.evaluate("() => window.__probe.fetches"):
            print("    %-6s %-58s %s  %s" % (item["method"], item["url"][-58:], item["status"], item["body"][:90]))
        browser.close()
    return 0


if __name__ == "__main__":
    sys.exit(main())

