INSTRUMENT = """
(() => {
  window.__ev = {events: [], esErrors: 0};
  const RealES = window.EventSource;
  window.EventSource = function (url) {
    const es = new RealES(url);
    window.__ev.url = String(url);
    es.addEventListener('message', e => window.__ev.events.push(['message', String(e.data).slice(0,120)]));
    for (const name of ['progress','template','done','diagnostic']) {
      es.addEventListener(name, e => window.__ev.events.push([name, String(e.data).slice(0,120)]));
    }
    es.addEventListener('error', () => { window.__ev.esErrors++; });
    return es;
  };
  window.EventSource.prototype = RealES.prototype;
  window.__poll = [];
})();
"""

POLL = """
async (ms) => {
  const out = [];
  const end = Date.now() + ms;
  while (Date.now() < end) {
    try {
      const r = await fetch('/api/scanner/nuclei/jobs/' + window.__jobId, {cache:'no-store'});
      const s = await r.json();
      const p = s.progress || {};
      out.push([s.state, p.percent, p.templates, p.requests_done, p.requests_total]);
    } catch (e) { out.push(['ERR', e.message]); }
    await new Promise(r => setTimeout(r, 3000));
  }
  return out;
}
"""


