// refreshHistoryDuringScan reloads History while a scan is producing exchanges,
// at most once every few seconds.
//
// WHY IT NEEDS ITS OWN PATH. History was reloaded from exactly three places: the
// Repeater sending a request, the Intruder poll noticing new results, and a tab
// switch. A Nuclei run was in none of them, so the exchanges it sends — which do
// arrive, and do land in History, measured growing from 603 to 631 records over a
// 30 s run of `javascript/` against a live target — stayed invisible until the
// operator left the tab and came back. A scanner that shows its own request
// counter climbing while the History tab beside it sits empty reads as a broken
// recording path, and the operator stopped the runs over it.
//
// The gate is the tab being open and a fixed interval, because a folder scan
// streams one row per template: reloading on every row would turn a 131-document
// folder into 131 requests of their own.
const HISTORY_LIVE_REFRESH_MS = 4000;
let historyLiveRefreshAt = 0;
function refreshHistoryDuringScan() {
  if (!$('history')?.classList.contains('active')) return;
  const now = Date.now();
  if (now - historyLiveRefreshAt < HISTORY_LIVE_REFRESH_MS) return;
  historyLiveRefreshAt = now;
  loadHistoryWithFilters();
}

// releaseScannerRunStream ends the live stream of a run that is no longer being
// followed, and settles its promise so nothing waits on it.

