// The running job is remembered so a reload re-attaches to it instead of
// abandoning it.
//
// This is the same contract Intruder already has — its `attack_id` goes into
// `localStorage` and the poll resumes on the next load — and a Nuclei run needs
// it more: a folder scan is minutes long, and reloading the page used to leave
// the binary running on the server with nothing on screen following it. The
// operator saw the panel empty and the scan still going, with no way back to it:
// the job id lived only in `scannerRun`, which a reload discards.
//
// The stored value is the job id alone. Whether the job is still alive is asked
// of the engine on restore rather than guessed, so a run that finished while the
// tab was closed is reported as finished instead of being followed forever.
const activeScanJobStorageKey = 'scanner-active-nuclei-job';
function rememberActiveScanJob(jobId) {
  try {
    if (jobId) localStorage.setItem(activeScanJobStorageKey, String(jobId));
    else localStorage.removeItem(activeScanJobStorageKey);
  } catch (error) {
    console.warn('Active scan job id could not be stored:', error);
  }
}

// restoreActiveScanJob re-attaches to a run a reload interrupted.
//
// It is silent when there is nothing to re-attach to. When the stored job is
// gone — finished long enough ago to be swept — the key is dropped so the next
// load does not ask again.
async function restoreActiveScanJob() {
  const stored = localStorage.getItem(activeScanJobStorageKey);
  if (!stored) return;
  let snapshot = null;
  try {
    const response = await fetch(`/api/scanner/nuclei/jobs/${encodeURIComponent(stored)}`, {cache: 'no-store'});
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    snapshot = await response.json();
  } catch (error) {
    rememberActiveScanJob(null);
    return;
  }
  if (!snapshot || !snapshot.progress) {
    rememberActiveScanJob(null);
    return;
  }
  const state = String(snapshot.state || '');
  if (state === 'completed' || state === 'failed' || state === 'cancelled') {
    rememberActiveScanJob(null);
    return;
  }
  // Still running. Re-open the stream from the cursor it reached, so the rows
  // that already arrived are not streamed a second time.
  scannerRun.jobId = stored;
  scannerRun.startedAt = Date.now();
  setScannerReportState('running');
  $('scanner-tpl-results').hidden = false;
  $('scanner-tpl-perfile-bar').hidden = false;
  $('scanner-templates-run').disabled = true;
