		t.Setenv("RR_MITM_IDLE_TIMEOUT_SEC", "12.5")
		if got := idleTimeoutFromEnv(); got != 12500*time.Millisecond {
			t.Fatalf("12.5 gave %v, want 12.5s", got)
		}
	})
}

