    source.addEventListener('error', () => {
      // EventSource reports a closed stream and a transport failure the same
      // way, so the job state is the only reliable way to tell them apart.
      //
      // A stream that drops while the job is still running is NOT a failed run.
      // Treating it as one is what produced `Scan failed` over a job the engine
      // was still working: measured on the full `http` corpus, the panel read
      // `Scan failed · The result stream was interrupted` at 800 s while
      // `GET /api/scanner/nuclei/jobs/<id>` answered `{"state":"running"}` with
      // the counter still moving. The operator was told the scan had ended while
      // the binary ran on, with no way back to it.
      //
      // So the two are separated: a live job is re-attached from the cursor it
      // reached, and only a job that is actually finished — or a state check
      // that cannot be completed at all, after the attempts are spent — ends the
      // run locally.
      const attempts = (scannerRun.streamReconnects || 0) + 1;
      scannerRun.streamReconnects = attempts;
      if (attempts > SCANNER_STREAM_RECONNECT_LIMIT) {
        source.close();
        finish(new Error(tr('scanner.streamInterrupted')));
        return;
      }
      fetch(`/api/scanner/nuclei/jobs/${encodeURIComponent(jobId)}`, {cache: 'no-store'})
        .then(response => response.json())
        .then(state => {
          if (state.state === 'completed') {
            source.close();
            finish(null, {state: 'completed', result: state.result, progress: scannerRun});
            return;
          }
          if (state.state === 'cancelled' || state.state === 'failed') {
            source.close();
            finish(Object.assign(new Error(state.reason || tr('scanner.progressFailed')), {
              cancelled: state.state === 'cancelled'
            }));
            return;
          }
          // Still running: the stream is what broke, not the scan. Re-attach from
          // the cursor so the rows that already arrived are not streamed twice —
          // the engine's `SubscribeSince` skips everything up to it, and the
          // name-keyed guard in `applyLiveTemplate` would drop duplicates anyway.
          source.close();
          scannerRun.source = null;
          followScannerJob(jobId, {onFinish, onError}).catch(() => {});
        })
        .catch(() => {
          // The state check itself failed. One retry, then the run is reported as
          // interrupted: a gateway that cannot be reached is a real condition,
          // and pretending the run is still fine would leave the panel claiming a
          // scan nobody can watch.
          if (attempts >= SCANNER_STREAM_RECONNECT_LIMIT) {
            source.close();
            finish(new Error(tr('scanner.streamInterrupted')));
            return;
          }
          setTimeout(() => {
            if (scannerRun.jobId === jobId && !scannerRun.finished) {
              followScannerJob(jobId, {onFinish, onError}).catch(() => {});
            }
          }, SCANNER_STREAM_RECONNECT_DELAY_MS);
        });
    });
  });
}

