// result instead of re-walking a folder that already holds thousands of files.
function scannerTemplateTally() {
  return {
    counts: {matched: 0, not_matched: 0, no_request: 0, skipped: 0, invalid: 0, duplicate: 0},
    ids: new Set(), findings: 0, withCve: 0, reason: '', total: 0
  };
}

function scannerTemplateTallyAdd(tally, item) {
  const status = String(item.status || 'not_matched');
  tally.counts[status] = (tally.counts[status] || 0) + 1;
  if (item.template_id) tally.ids.add(item.template_id);
  // A streamed result carries the match count while the finished report carries
  // the findings themselves, so the higher of the two is the number of hits the
  // file produced. The folder line therefore reads the same before and after.
  tally.findings += Math.max(
    Number(item.matches) || 0,
    Array.isArray(item.findings) ? item.findings.length : 0
  );
  if ((item.cve || []).length || (item.cwe || []).length) tally.withCve += 1;
  if (!tally.reason && (status === 'invalid' || status === 'skipped' || status === 'duplicate')) {
    tally.reason = item.reason || (status === 'invalid'
      ? tr('scanner.perFileInvalidReason')
      : status === 'duplicate'
        ? tr('scanner.perFileDuplicateReason')
        : tr('scanner.perFileSkippedReason'));
  }
  tally.total += 1;
  return tally;
}

// scannerTemplateSummary is the per-folder tally. It is computed from the files
// the folder really holds, so a counter can never claim a file the binary did not
// report, and the reason shown is a reason the run actually produced.
function scannerTemplateSummary(items) {
  const tally = scannerTemplateTally();
  items.forEach(item => scannerTemplateTallyAdd(tally, item));
  return {...tally, ids: tally.ids.size};
}

