// scannerTemplateFolderInsertPoint returns the row a newly seen folder goes
// before: the first folder row whose folder sorts after it.
function scannerTemplateFolderInsertPoint(folder) {
  const body = $('scanner-tpl-body');
  if (!body) return null;
  for (const row of [...body.children]) {
    if (!row.dataset || row.dataset.folder === undefined) continue;
    if (String(row.dataset.folder).localeCompare(folder) > 0) return row;
  }
  return null;
}

// updateLiveScannerFolderRow grows a folder row in place, so a streaming result
// never re-renders a table the operator may be reading. Only the parts that can
// change are touched: the counters, and the reason cell the first time the folder
// turns out to hold a file the binary did not run.
function updateLiveScannerFolderRow(live, item) {
  const summary = live.tally;
  const files = live.row.querySelector('.scanner-folder-total');
  if (files) files.textContent = scannerTemplateFolderScope(summary.total);
  // Every number a folder row shows is refreshed from the running tally, so a
  // streamed folder never displays the values of the single file that opened it.
  const ids = live.row.querySelector('.scanner-folder-ids');
  if (ids) ids.textContent = String(summary.ids.size);
  const cve = live.row.querySelector('.scanner-folder-cve');
  if (cve) {
    cve.textContent = String(summary.withCve);
  } else if (summary.withCve) {
