function setScannerReportState(state) {
  const panel = $('scanner-tpl-results');
  if (panel) panel.setAttribute('data-report-state', state);
}

function showScannerTemplateReport(data, statusMessage) {
  scannerTemplateReport = Array.isArray(data.templates) ? data.templates : [];
  // A run that reports its own total is authoritative; otherwise the rows on
  // screen are the whole of it.
  const reported = Number(data.templatesTotal || 0);
  scannerTemplateTotal = reported > scannerTemplateReport.length ? reported : scannerTemplateReport.length;
  const hasReport = scannerTemplateReport.length > 0;
  $('scanner-tpl-results').hidden = !hasReport;
  $('scanner-tpl-perfile-title').hidden = !hasReport;
  $('scanner-tpl-perfile-bar').hidden = !hasReport;
  setScannerReportState(hasReport ? 'report' : 'empty');
  if (!hasReport) {
    $('scanner-tpl-body').replaceChildren();
    $('scanner-tpl-perfile-stats').textContent = '';
    $('scanner-tpl-more').hidden = true;
    scannerTemplateEntries = [];

    scannerTemplateEntries = [];
    scannerTemplateExpanded = new Set();
    scannerTemplateLiveFolders = new Map();
    syncScannerFolderToggle();
    return;
  }
  renderScannerTemplateStats(data);
  renderScannerTemplateReport();
  const stats = data.stats && typeof data.stats === 'object' ? data.stats : {};
  const exitCode = Number(stats.exit_code);
  const hasExitCode = stats.exit_code !== null && stats.exit_code !== undefined;
  // Nuclei emits normal progress and version output on stderr for successful runs.
  const failed = stats.exit_status === 'failed'
    || Boolean(stats.error)
    || (stats.exit_status !== 'partial' && hasExitCode && Number.isFinite(exitCode) && exitCode !== 0);
  if (failed) {
    $('scanner-status').textContent = `${statusMessage} ${tr('scanner.runFailed', {
      code: stats.exit_code ?? '', status: stats.exit_status || ''
    })}`;
  } else {
    $('scanner-status').textContent = statusMessage;
  }
  // The full binary output is already on screen in the diagnostics block, which
  // scrolls. It is deliberately not repeated into the progress line: with a
  // folder of thousands of templates that output is megabytes, and inlining it
  // here grew the page to hundreds of thousands of pixels and buried the report.
  const node = $('scanner-upload-progress');
  if (node) {
    node.hidden = true;
    node.textContent = '';
  }
}

