function scannerTemplateSummary(items) {
  const tally = scannerTemplateTally();
  items.forEach(item => scannerTemplateTallyAdd(tally, item));
  return {...tally, ids: tally.ids.size};
}

// scannerFolderMatcherText names what a folder matched on, or '' when it matched
// nothing it can name. Both the table and the exported report read this, so the
// two never disagree about the same run.
//
// A folder row's details cell used to carry a reason and nothing else, and a
// reason only ever exists for a file that was refused, never run, or reported as a
// copy — so a matched folder rendered "—" right beside "MATCHED · N", on the
// widest column, while the same row announced "N findings in the folder". The
// matcher names are in the payload; nothing had ever put them on screen there.
//
// The names are data, not interface text, so they read identically in both
// languages and need no dictionary key. Four fit the column beside the other
// cells; the rest are counted, never dropped, and each one is written out in full
