function exportScannerView(view, format) {
  const data = scannerViewResult(view);
  if (!data || !format) return;
  const stamp = Date.now();
  if (format === 'json') {
    downloadJSON(`scanner-${view}-${stamp}.json`, data);
    flashExportMenu(view, 'JSON');
    return;
  }
  if (format === 'csv') {
    // One row per finding, the way the per-template export is one row per file: a
    // flat section/field/value dump of an active run makes a reviewer count rows
    // to find out how many findings there were, and it loses the tier — which is
    // the field that separates a proven impact from a pattern that resembles one.
    const rows = data.engine === 'nuclei' ? scannerNucleiCsvRows(data)
      : data.engine === 'active' ? scannerActiveCsvRows(data)
      : scannerGenericCsvRows(data);
    downloadTarget(`scanner-${view}-${stamp}.csv`, scannerCsvText(rows), 'text/csv;charset=utf-8');
    flashExportMenu(view, 'CSV');
    return;
  }
  if (format === 'html') {
    // The self-contained HTML report is rendered here, in the browser, for every
    // view — CMS, Nuclei and Active alike. That is the report the operator has
    // always received from this menu and it stays byte-for-byte the product it
    // was: one file, no server round trip, no request that can be refused.
    //
    // `/api/scanner/report` remains available and keeps its allow-list
    // validation and Django escaping, but it is not what this button writes.
    // Routing the download through it was a change of the product's behaviour,
    // not a security improvement: a refusal mid-run turns an export that worked
    // into an error, and the operator loses the report of a finished scan.
    downloadTarget(`scanner-${view}-${stamp}.html`, scannerHtmlReport(view, data), 'text/html;charset=utf-8');
    flashExportMenu(view, 'HTML');
  }
}

// flashExportMenu confirms the chosen format briefly, so the menu click is
// never silent. The label is drawn in CSS so the trigger keeps its icon.
function flashExportMenu(view, label) {
  const trigger = exportMenuTrigger(view);
  if (!trigger) return;
  trigger.setAttribute('data-export-flash', label);
  trigger.classList.add('is-exported');
  window.clearTimeout(trigger._exportFlashTimer);
  trigger._exportFlashTimer = window.setTimeout(() => {
    trigger.classList.remove('is-exported');
    trigger.removeAttribute('data-export-flash');
  }, 1800);
}

