package main

import (
	"context"
	"net/http"
	"os"
	"strings"
	"sync"
	"testing"
	"time"
)

// sourceIPLookupConcurrency reads one environment variable every call, so the
// tests can set and unset it without a rebuild. The semaphore, by contrast, is
// built once at process start — so the tests that need a known capacity fill and
// restore it themselves rather than depending on the ambient environment.
func TestSourceIPLookupConcurrencyHonoursTheEnvironment(t *testing.T) {
	t.Setenv("RR_SOURCE_IP_LOOKUP_CONCURRENCY", "")
	if got := sourceIPLookupConcurrency(); got != sourceIPLookupConcurrencyDefault {
		t.Fatalf("empty env: got %d, want the default %d", got, sourceIPLookupConcurrencyDefault)
	}
	for _, bad := range []string{"0", "-4", "abc", "12.5", "  "} {
		t.Setenv("RR_SOURCE_IP_LOOKUP_CONCURRENCY", bad)
		if got := sourceIPLookupConcurrency(); got != sourceIPLookupConcurrencyDefault {
			t.Fatalf("env=%q: got %d, want the default %d", bad, got, sourceIPLookupConcurrencyDefault)
		}
	}
	for _, value := range []string{"1", "16", " 64 "} {
		t.Setenv("RR_SOURCE_IP_LOOKUP_CONCURRENCY", value)
		want := 0
		for _, r := range strings.TrimSpace(value) {
			want = want*10 + int(r-'0')
		}
		if got := sourceIPLookupConcurrency(); got != want {
			t.Fatalf("env=%q: got %d, want %d", value, got, want)
		}
	}
}

// The bound has to be visible, or it is the kind of limit the operator cannot
// find or change. This reads the same map the engine serves in its `bound` block.
func TestSourceIPLookupBoundIsReportedWithItsOverride(t *testing.T) {
	t.Setenv("RR_SOURCE_IP_LOOKUP_CONCURRENCY", "12")
	described := loadTransportBounds().describe()

	value, ok := described["source_ip_lookup_concurrency"]
	if !ok {
		t.Fatal("source_ip_lookup_concurrency is missing from the reported bounds")
	}
	if value != 12 {
		t.Fatalf("reported %v, want the 12 the environment asked for", value)
	}
	overrides, _ := described["overrides"].([]string)
	for _, name := range overrides {
		if name == "RR_SOURCE_IP_LOOKUP_CONCURRENCY" {
			return
		}
	}
	t.Fatalf("RR_SOURCE_IP_LOOKUP_CONCURRENCY is not listed among the overrides: %v", overrides)
}

// The bound must actually bound: with every slot taken, a lookup cannot open a
// request, and it must give up on its own deadline rather than wait forever.
func TestSourceIPLookupRefusedWhenEverySlotIsBusy(t *testing.T) {
	engine := &server{transport: &http.Transport{}, sourceIPTransport: &countingRoundTripper{}}

	restore := fillSourceIPLookupSlots(t)
	defer restore()
	t.Setenv("RR_SOURCE_IP_LOOKUP_TIMEOUT_MS", "120")

	started := time.Now()
	ip := engine.lookupSourceIP(context.Background())
	elapsed := time.Since(started)

	if ip != "" {
		t.Fatalf("a lookup with no free slot returned %q; it must return nothing", ip)
	}
	if requests := engine.sourceIPTransport.(*countingRoundTripper).calls(); requests != 0 {
		t.Fatalf("a lookup with no free slot still made %d request(s); the bound did not hold", requests)
	}
	if elapsed > 2*time.Second {
		t.Fatalf("a refused lookup took %s; it must give up on its own deadline", elapsed)
	}
}

// A slot taken must be given back, or the bound would be a one-way ratchet that
// silences the field after the first N exchanges of a long scan. Two sequential
// lookups both succeeding is what proves the release.
func TestSourceIPLookupReleasesItsSlot(t *testing.T) {
	rt := &countingRoundTripper{}
	engine := &server{transport: &http.Transport{}, sourceIPTransport: rt}
	t.Setenv("RR_SOURCE_IP_LOOKUP_TIMEOUT_MS", "5000")

	first := engine.lookupSourceIP(context.Background())
	second := engine.lookupSourceIP(context.Background())

	if first == "" || second == "" {
		t.Fatalf("sequential lookups returned %q then %q; a slot was not released", first, second)
	}
	if got := rt.calls(); got != 2 {
		t.Fatalf("made %d request(s) for two lookups; a slot was not released", got)
	}
}

// Under load the number of lookups in flight stays at the bound. The point is
// the maximum, not the total: every lookup still runs, they simply stop all
// running at once.
func TestSourceIPLookupNeverExceedsItsBound(t *testing.T) {
	const bound = 4
	rt := &peakRoundTripper{}
	engine := &server{transport: &http.Transport{}, sourceIPTransport: rt}

	restore := swapSourceIPLookupSlots(bound)
	defer restore()
	t.Setenv("RR_SOURCE_IP_LOOKUP_TIMEOUT_MS", "5000")

	var group sync.WaitGroup
	for i := 0; i < 32; i++ {
		group.Add(1)
		go func() {
			defer group.Done()
			engine.lookupSourceIP(context.Background())
		}()
	}
	group.Wait()

	if peak := rt.peak(); peak > bound {
		t.Fatalf("peak in-flight lookups was %d, above the bound of %d", peak, bound)
	}
	if total := rt.calls(); total != 32 {
		t.Fatalf("made %d request(s) for 32 lookups; the bound must not drop work", total)
	}
}

func fillSourceIPLookupSlots(t *testing.T) func() {
	t.Helper()
	return swapSourceIPLookupSlots(sourceIPLookupConcurrency())
}

// swapSourceIPLookupSlots installs a semaphore of the given capacity and returns
// a function that puts the process-wide one back.
func swapSourceIPLookupSlots(capacity int) func() {
	previous := sourceIPLookupSlots
	sourceIPLookupSlots = make(chan struct{}, capacity)
	slots := sourceIPLookupSlots
	for i := 0; i < capacity; i++ {
		slots <- struct{}{}
	}
	return func() { sourceIPLookupSlots = previous }
}

