type corpusEvent struct {
	ID      int                    `json:"id"`
	Kind    string                 `json:"kind"`
	Payload map[string]interface{} `json:"payload"`
}

// subscribe attaches a listener and returns the channel plus its detach
// function. A detached listener is closed, and publishing to a closed channel is
// what panics, so detach is the only way out and the stream defers it.
func (j *corpusJob) subscribe() (<-chan corpusEvent, func()) {
	channel := make(chan corpusEvent, 64)
	j.subsMu.Lock()
	if j.subs == nil {
		j.subs = map[int]chan corpusEvent{}
	}
	id := j.nextSub
	j.nextSub++
	j.subs[id] = channel
	j.subsMu.Unlock()
	return channel, func() {
		j.subsMu.Lock()
		if existing, ok := j.subs[id]; ok {
			delete(j.subs, id)
			close(existing)
		}
		j.subsMu.Unlock()
	}
