func (s *server) scannerCorpusJobs(w http.ResponseWriter, r *http.Request) {
	switch {
	case r.Method == http.MethodPost && r.URL.Path == "/proxy/scanner/corpus/jobs":
		s.startCorpusJob(w, r)
	case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/stream"):
		s.streamCorpusJob(w, r)
	case r.Method == http.MethodGet:
		s.reportCorpusJob(w, r)
	case r.Method == http.MethodDelete:
		s.cancelCorpusJob(w, r)
	default:
		writeError(w, http.StatusMethodNotAllowed, "METHOD_NOT_ALLOWED",
			fmt.Errorf("method %s not allowed", r.Method))
	}
}

// streamCorpusJob pushes progress and findings to the browser while the run
// continues, and ends with one authoritative frame.
//
// The first frame is the job as it stands, not the next event. A browser that
// connects late, or reconnects after a dropped connection, therefore starts from
// the truth rather than from whatever happens to arrive next — and `Last-Event-ID`
// needs no replay buffer to be correct.
//
// A corpus run has no natural heartbeat: a quiet stretch is a slow target, not a
// dead job. The keepalive comment below keeps the connection through those
// stretches, because a stream that only wrote bytes on real progress was
// indistinguishable from a hung scan.
func (s *server) streamCorpusJob(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimSuffix(strings.TrimPrefix(r.URL.Path, "/proxy/scanner/corpus/jobs/"), "/stream")
	job := s.corpusJob(id)
	if job == nil {
		writeError(w, http.StatusNotFound, "UNKNOWN_JOB", fmt.Errorf("no corpus job %q", id))
		return
	}

	flusher, ok := w.(http.Flusher)
	if !ok {
		writeError(w, http.StatusInternalServerError, "STREAM_UNSUPPORTED",
			fmt.Errorf("streaming is not supported by this connection"))
		return
	}
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("X-Accel-Buffering", "no")
	w.WriteHeader(http.StatusOK)

	events, detach := job.subscribe()
	defer detach()

	send := func(kind string, payload map[string]interface{}) bool {
		// Every frame carries the job's own monotonic id, so the browser's
		// `Last-Event-ID` on reconnect names a real position in this job's
		// history rather than a number that means nothing.
		job.subsMu.Lock()
		job.seq++
		id := job.seq
		job.subsMu.Unlock()
		data, err := json.Marshal(payload)
		if err != nil {
			return true
		}
		if _, err := fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", id, kind, data); err != nil {
			return false
		}
		flusher.Flush()
		return true
	}

	if !send("snapshot", job.snapshot()) {
		return
	}

