  }

  function appendLiveCorpusFinding(finding) {
    if (!finding) return;
    // The stream and the terminal frame both deliver the same rows, so a finding
    // is keyed rather than appended blindly: a duplicate row would read as two
    // separate results from one request.
    const key = [finding.method, finding.path, finding.status, finding.check_id || finding.check || finding.id].join('|');
