  // toggleCorpusRow opens or closes the detail row under a finding. Only one row
  // stays open: a report with twenty expanded panels is not a report, and the
  // evidence is long enough that opening many fills the section.
  function toggleCorpusRow(row, item) {
    const wasOpen = row.getAttribute('aria-expanded') === 'true';
    document.querySelectorAll('#scanner-corpus-rows tr.corpus-detail-row').forEach(detail => detail.remove());
    document.querySelectorAll('#scanner-corpus-rows tr[aria-expanded="true"]').forEach(open => open.setAttribute('aria-expanded', 'false'));
