    detail.className = 'corpus-detail-row';
    const cell = document.createElement('td');
    cell.colSpan = 6;
    const label = document.createElement('div');
    label.className = 'corpus-detail-label';
    label.textContent = tr('scanner.corpusDetailTitle');
